script:
frappe.ui.form.on('Sales Invoice', {
    refresh: function(frm){
        if (frm.doc.excel_invoice_type == 'Completed Project') {
            frm.set_df_property('custom_handover_date', 'hidden', 0);
            frm.refresh_field('custom_handover_date');
            if(frm.doc.docstatus == 1){
               frm.set_df_property( 'excel_invoice_type', 'read_only', 1); 
               frm.refresh_field('excel_invoice_type');

               frm.set_df_property( 'custom_handover_date', 'read_only', 1); 
               frm.refresh_field('custom_handover_date');


            }

        } else {
            frm.set_df_property('custom_handover_date', 'hidden', 1); 
            frm.refresh_field('custom_handover_date');

        }

    },
    excel_invoice_type : function(frm){
         if (frm.doc.excel_invoice_type == 'Completed Project') {
            frm.set_df_property('custom_handover_date', 'hidden', 0);
            frm.refresh_field('custom_handover_date');
             if(frm.doc.docstatus == 1){
              frm.set_df_property( 'excel_invoice_type', 'read_only', 1); 
              frm.refresh_field('excel_invoice_type');
            }

        } 

        // else {
        //     frm.set_df_property('custom_handover_date', 'hidden', 1); 
        //     frm.refresh_field('custom_handover_date');

        // }
    },
    validate: function(frm) {
        let today = frappe.datetime.nowdate();
        let handover_date = frm.doc.custom_handover_date;
        const invoice_type = frm.doc.excel_invoice_type;
        if (handover_date && handover_date < today && invoice_type=== "Completed Project") {
            frappe.msgprint(__('Handover Date cannot be earlier than today.'));
            frappe.validated = false;
        }
    }


});

frappe.ui.form.on('Payment Entry', {
    validate: function(frm) {
        const territory = frm.doc.excel_territory;
        console.log("Territory: ", territory);

        if (territory === "Corporate" || territory === "TENDER") {
            let all_rows_valid = true;

            frm.doc.references.forEach((reference, index) => {
                if (flt(reference.outstanding_amount) !== flt(reference.allocated_amount)) {
                    if (!reference.custom_outstanding_types) {
                        console.log(`Outstanding Types is missing for row ${index + 1}`);
                        frappe.msgprint(__('Outstanding Types must be filled for all rows with mismatched Outstanding Amount and Allocated Amount.'));
                        frm.fields_dict['references'].grid.get_field('custom_outstanding_types').reqd = 1;
                        all_rows_valid = false;
                    }
                }
            });

            if (!all_rows_valid) {
                frappe.validated = false;
            }
        }
    },

    on_save: function(frm) {
        // Return a promise that resolves when all updates are done
        return new Promise((resolve) => {
            if (!frm.doc.references || frm.doc.references.length === 0) {
                resolve();
                return;
            }

            let updatePromises = [];

            frm.doc.references.forEach(reference => {
                if (reference.custom_outstanding_types && reference.reference_name) {
                    updatePromises.push(
                        new Promise((innerResolve) => {
                            frappe.call({
                                method: 'frappe.client.get',
                                args: {
                                    doctype: 'Sales Invoice',
                                    name: reference.reference_name
                                },
                                callback: function(r) {
                                    if (r.message) {
                                        const sales_invoice = r.message;
                                        sales_invoice.custom_outstanding_types = reference.custom_outstanding_types;

                                        frappe.call({
                                            method: 'frappe.client.save',
                                            args: {
                                                doc: sales_invoice
                                            },
                                            callback: function() {
                                                innerResolve();
                                            }
                                        });
                                    } else {
                                        innerResolve();
                                    }
                                }
                            });
                        })
                    );
                }
            });

            Promise.all(updatePromises).then(() => {
                resolve();
            });
        });
    }
});

frappe.ui.form.on('User Permission', {
    for_value(frm) {
        // Check if the doctype is 'Sales Person'
        if (frm.doc.allow === 'Sales Person' && frm.doc.for_value) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Sales Person',
                    name: frm.doc.for_value
                },
                callback: function(r) {
                    if (r.message) {
                        const sales_person = r.message;
                        // Assuming email_id is a field in Sales Person
                        frm.set_value('custom_sales_person_email', sales_person.excel_sales_person_email || '');
                        frm.refresh_field('custom_sales_person_email')
                    }
                }
            });
        }
    }
});
